package com.orbitcrm.chat.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * Request to send a message.
 *
 * <p>Purpose: sending again with the same {@code clientId} returns the original message instead of creating a
 * duplicate, so the app can safely retry after a network error.
 *
 * @author Abhay
 * @param clientId id generated by the app for this message (for example a UUID)
 * @param body     text, up to {@value #MAX_BODY} characters
 */
public record SendMessageRequest(@NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9_-]+") String clientId,
                                 @NotBlank @Size(max = SendMessageRequest.MAX_BODY) String body) {

    public static final int MAX_BODY = 4000;
}
